public str getName()
{
    return fieldPName(InventDim, InventDimension8);
}

public Set getAllowedValues()
{
    var ret = new Set(Types::String);
    InventDim inventDim;
    while select InventDimension8 from inventDim
        group by InventDimension8
    {
        ret.add(inventDim.InventDimension8);
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(InventDim, InventDimension8));
    qbr.value(queryValue(_value));
}
